REVOKE INSERT ON public.recycling_logs, public.recycling_log_items FROM authenticated, anon;
CREATE OR REPLACE FUNCTION public.record_recycling(_client uuid,_point uuid,_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; total numeric:=0; carbon numeric:=0; reward integer; i jsonb; m materials%ROWTYPE; k numeric; n integer; sz text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; IF _client IS NULL THEN RAISE EXCEPTION 'Identificador requerido'; END IF; IF _point IS NOT NULL AND NOT EXISTS(SELECT 1 FROM collection_points WHERE id=_point) THEN RAISE EXCEPTION 'Punto inválido'; END IF; IF _items IS NULL OR jsonb_typeof(_items)<>'array' THEN RAISE EXCEPTION 'Agrega materiales'; END IF; IF jsonb_array_length(_items)<1 OR jsonb_array_length(_items)>50 THEN RAISE EXCEPTION 'Agrega materiales'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text || _client::text)); SELECT id INTO lid FROM recycling_logs WHERE user_id=auth.uid() AND client_id=_client; IF lid IS NOT NULL THEN RETURN lid; END IF; FOR i IN SELECT * FROM jsonb_array_elements(_items) LOOP IF jsonb_typeof(i)<>'object' OR jsonb_typeof(i->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(i->'n') IS DISTINCT FROM 'number' OR jsonb_typeof(i->'size') IS DISTINCT FROM 'string' OR (i->>'n')!~'^[0-9]+$' THEN RAISE EXCEPTION 'Material, cantidad o tamaño inválido'; END IF; SELECT * INTO m FROM materials WHERE id=i->>'id'; IF NOT FOUND THEN RAISE EXCEPTION 'Material inválido'; END IF; n:=(i->>'n')::integer; sz:=i->>'size'; IF n<1 OR n>10000 OR sz NOT IN ('pequeno','mediano','grande') THEN RAISE EXCEPTION 'Cantidad o tamaño inválido'; END IF; k:=n*CASE sz WHEN 'pequeno' THEN m.kg_pequeno WHEN 'grande' THEN m.kg_grande ELSE m.kg_mediano END; IF k<=0 OR k::text IN ('NaN','Infinity','-Infinity') OR m.co2_por_kg<0 OR m.co2_por_kg::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Factor de material inválido'; END IF; total:=total+k; carbon:=carbon+k*m.co2_por_kg; END LOOP; reward:=least(500,round(total*10)::integer+jsonb_array_length(_items)*2); INSERT INTO recycling_logs(user_id,point_id,kg_total,co2_total,puntos,client_id) VALUES(auth.uid(),_point,total,carbon,reward,_client) RETURNING id INTO lid; FOR i IN SELECT * FROM jsonb_array_elements(_items) LOOP SELECT * INTO m FROM materials WHERE id=i->>'id'; sz:=i->>'size'; k:=(i->>'n')::integer*CASE sz WHEN 'pequeno' THEN m.kg_pequeno WHEN 'grande' THEN m.kg_grande ELSE m.kg_mediano END; INSERT INTO recycling_log_items(log_id,material_id,tamano,cantidad,kg) VALUES(lid,m.id,sz,(i->>'n')::integer,k); END LOOP; RETURN lid; END $$;
CREATE OR REPLACE FUNCTION public.validate_point_suggestion() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.nota)>2000 OR length(NEW.horario)>500 THEN RAISE EXCEPTION 'Texto demasiado largo'; END IF; IF (NEW.lat IS NULL)<>(NEW.lng IS NULL) OR (NEW.lat IS NOT NULL AND NOT (NEW.lat BETWEEN -90 AND 90 AND NEW.lng BETWEEN -180 AND 180)) THEN RAISE EXCEPTION 'Coordenadas inválidas'; END IF; IF NEW.materiales IS NOT NULL AND (cardinality(NEW.materiales)<1 OR cardinality(NEW.materiales)>50 OR EXISTS(SELECT 1 FROM unnest(NEW.materiales) x WHERE x IS NULL OR NOT EXISTS(SELECT 1 FROM materials WHERE id=x))) THEN RAISE EXCEPTION 'Materiales inválidos'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_suggestion BEFORE INSERT OR UPDATE ON public.point_suggestions FOR EACH ROW EXECUTE FUNCTION public.validate_point_suggestion();
REVOKE ALL ON public.push_keys, public.push_deliveries FROM anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.record_recycling(uuid,uuid,jsonb) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.record_recycling(uuid,uuid,jsonb) TO authenticated;